  "\u21AA \u043A \u043C\u0435\u0441\u0442\u0443 \u0432 \u043A\u043D\u0438\u0433\u0435": "\u21AA \u8FD4\u56DE\u539F\u6587",
  "\u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u0442\u0435\u043A\u0441\u0442\u0443": "\u8FD4\u56DE\u539F\u6587",
  "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u043C\u0435\u0441\u0442\u043E \u0432 \u043A\u043D\u0438\u0433\u0435 \u043F\u043E\u0434 \u0446\u0438\u0442\u0430\u0442\u043E\u0439": "\u4E3A\u6458\u5F55\u6DFB\u52A0\u201C\u8FD4\u56DE\u539F\u6587\u201D\u94FE\u63A5",
  "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \xAB{0}\xBB \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u0432\u043A\u043B\u0430\u0434\u043A\u0435?": "\u8981\u5728\u65B0\u6807\u7B7E\u9875\u6253\u5F00\u7B14\u8BB0\u201C{0}\u201D\u5417\uFF1F",
  "\u0414\u0430, \u043E\u0442\u043A\u0440\u044B\u0442\u044C": "\u6253\u5F00",
  "\u0414\u0430": "\u662F",
  "\u041D\u0435\u0442": "\u5426",
