      __ertr("\xAB\u041F\u0430\u043C\u044F\u0442\u044C \u043E \u043A\u043D\u0438\u0433\u0430\u0445\xBB \u2014 \u043A\u043D\u043E\u043F\u043A\u0430 \xAB\u0417\u0430\u0431\u044B\u0442\u044C \u0432\u0441\u0435 \u043A\u043D\u0438\u0433\u0438\xBB \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u043F\u0440\u0438\u0432\u044F\u0437\u043A\u0438 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u0438 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439, \u043D\u043E \u0441\u0430\u043C\u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u043D\u0435 \u0443\u0434\u0430\u043B\u044F\u0435\u0442. \u041D\u0443\u0436\u043D\u0430, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0432\u0441\u0451 \u0437\u0430\u043D\u043E\u0432\u043E.")
