    const title = sanitizeNoteTitle(`Qiaomu Book Reader ${plugin.manifest.version} \u2014 ${__ertr("\u0427\u0442\u043E \u043D\u043E\u0432\u043E\u0433\u043E")}`);
    const path5 = inboxNotePath(app, title, null);
    const exist = app.vault.getAbstractFileByPath(path5);
    if (exist instanceof import_obsidian.TFile) return exist;
    const body = releases.map((r) => `## ${r.v}

${r.items.map((i) => `- ${__ertr(i)}`).join("\n")}`).join("\n\n");
    await resolveNotesFolder(app, null);
    const f = await app.vault.create(path5, `${__ertr("\u041A\u043D\u0438\u0436\u043D\u0430\u044F \u0447\u0438\u0442\u0430\u043B\u043A\u0430 \u043E\u0431\u043D\u043E\u0432\u0438\u043B\u0430\u0441\u044C \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {0}. \u0427\u0442\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u043E\u0441\u044C:", plugin.manifest.version)}

${body}
`);
    return f instanceof import_obsidian.TFile ? f : null;
